<?php
require_once 'sacco_common.php';$mid=(int)($_GET['id']??0);if(!$mid)die('Invalid membership ID.');
$sql=sacco_member_select_sql()." WHERE m.sacco_member_id=?";$st=$conn->prepare($sql);$st->bind_param('i',$mid);$st->execute();$member=$st->get_result()->fetch_assoc();$st->close();if(!$member)die('Membership not found.');
$from=$_GET['from']??'';$to=$_GET['to']??'';$w='sacco_member_id=?';$p=[$mid];$b='i';
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$w.=' AND transaction_date>=?';$p[]=$from;$b.='s';}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$w.=' AND transaction_date<=?';$p[]=$to;$b.='s';}
$st=$conn->prepare("SELECT * FROM hr_sacco_transactions WHERE $w ORDER BY transaction_date,transaction_id");$st->bind_param($b,...$p);$st->execute();$res=$st->get_result();
$items=[];$run=0;$credits=0;$debits=0;while($r=$res->fetch_assoc()){$credit=in_array($r['transaction_type'],['opening_balance','contribution','adjustment_credit'],true);$signed=$credit?(float)$r['amount']:-((float)$r['amount']);$run+=$signed;if($signed>0)$credits+=$signed;else $debits+=abs($signed);$r['signed']=$signed;$r['running']=$run;$items[]=$r;}
$current=sacco_balance($conn,$mid);require_once 'navbar.php';
?>
