<div class="bg-white border rounded-xl p-5 mb-5 grid md:grid-cols-2 gap-4"><div><p class="text-xs text-gray-500 uppercase">Employee</p><h2 class="text-xl font-bold"><?=se($member['full_name'])?></h2></div><div><p class="text-xs text-gray-500 uppercase">SACCO</p><h2 class="text-xl font-bold"><?=se($member['sacco_name'])?></h2><p class="text-sm text-gray-500">Account: <?=se($member['sacco_account_no']?:'—')?> | Joined: <?=se($member['membership_date']?:'—')?></p></div></div>
<form method="get" class="bg-white border rounded-xl p-4 mb-5 flex flex-wrap gap-3 items-end"><input type="hidden" name="id" value="<?=$mid?>"><label class="text-sm">From<input type="date" name="from" value="<?=se($from)?>" class="block border rounded p-2"></label><label class="text-sm">To<input type="date" name="to" value="<?=se($to)?>" class="block border rounded p-2"></label><button class="bg-blue-600 text-white rounded px-4 py-2">Filter</button><a href="sacco_member_statement.php?id=<?=$mid?>" class="text-blue-600 py-2">Clear</a></form>
<div class="grid sm:grid-cols-3 gap-4 mb-5"><div class="bg-white border rounded p-4">Current balance<b class="block text-2xl text-blue-700">KSh <?=sm($current)?></b></div><div class="bg-white border rounded p-4">Credits in period<b class="block text-xl text-green-700">KSh <?=sm($credits)?></b></div><div class="bg-white border rounded p-4">Debits in period<b class="block text-xl text-orange-600">KSh <?=sm($debits)?></b></div></div>
<div class="bg-white border rounded-xl overflow-x-auto"><table class="w-full text-sm"><thead class="bg-gray-100"><tr><th class="p-3 text-left">Date</th><th class="p-3 text-left">Transaction</th><th class="p-3 text-left">Month</th><th class="p-3 text-right">Credit</th><th class="p-3 text-right">Debit</th><th class="p-3 text-right">Running balance</th></tr></thead><tbody><?php if($items):foreach($items as $r):?><tr class="border-t"><td class="p-3"><?=se($r['transaction_date'])?></td><td class="p-3"><?=se(sacco_type_label($r['transaction_type']))?><div class="text-xs text-gray-500"><?=se($r['description'])?> <?=se($r['reference_number'])?></div></td><td class="p-3"><?=$r['contribution_month']?se(date('M Y',strtotime($r['contribution_month']))):'—'?></td><td class="p-3 text-right text-green-700"><?=$r['signed']>0?sm($r['signed']):'—'?></td><td class="p-3 text-right text-red-600"><?=$r['signed']<0?sm(abs($r['signed'])):'—'?></td><td class="p-3 text-right font-semibold"><?=sm($r['running'])?></td></tr><?php endforeach;?><?php else:?><tr><td colspan="6" class="p-8 text-center text-gray-500">No transactions for this period.</td></tr><?php endif;?></tbody></table></div><p class="text-xs text-gray-500 mt-2">Running balance starts at the beginning of the selected period; current balance is the all-time balance.</p></main>
